#!/usr/bin/env node
const fs = require('fs');
const path = require('path');
const os = require('os');
const https = require('https');
const { getCredential } = require('../../../scripts/lib/credentials.js');

const PRO_WORKFLOW_ROOT = path.resolve(__dirname, '..', '..', '..');
const COUNCIL_ROOT = path.join(os.homedir(), '.pro-workflow', 'council');

const PROVIDERS = {
  anthropic: {
    envKey: 'ANTHROPIC_API_KEY',
    baseUrl: 'https://api.anthropic.com',
    defaultModels: ['claude-opus-5-5', 'claude-sonnet-5', 'claude-haiku-4-5'],
    defaultChairman: 'claude-opus-5-5',
    call: callAnthropic,
  },
  openai: {
    envKey: 'OPENAI_API_KEY',
    baseUrl: 'https://api.openai.com/v1',
    defaultModels: ['gpt-4o', 'gpt-4o-mini', 'o3-mini'],
    defaultChairman: 'gpt-4o',
    call: callOpenAICompat,
  },
  openrouter: {
    envKey: 'OPENROUTER_API_KEY',
    baseUrl: 'https://openrouter.ai/api/v1',
    defaultModels: ['anthropic/claude-opus-4', 'openai/gpt-4o', 'google/gemini-2.0-flash'],
    defaultChairman: 'anthropic/claude-opus-4',
    call: callOpenAICompat,
  },
  fireworks: {
    envKey: 'FIREWORKS_API_KEY',
    baseUrl: 'https://api.fireworks.ai/inference/v1',
    defaultModels: [
      'accounts/fireworks/models/glm-5',
      'accounts/fireworks/models/deepseek-v3p2',
      'accounts/fireworks/models/kimi-k2p5',
    ],
    defaultChairman: 'accounts/fireworks/models/glm-5',
    call: callOpenAICompat,
  },
  custom: {
    envKey: 'LLM_COUNCIL_API_KEY',
    baseUrl: process.env.LLM_COUNCIL_BASE_URL || '',
    defaultModels: (process.env.LLM_COUNCIL_MODELS || '').split(',').filter(Boolean),
    defaultChairman: process.env.LLM_COUNCIL_CHAIRMAN || '',
    call: callOpenAICompat,
  },
};

function pickProvider(arg) {
  if (arg) return Object.hasOwn(PROVIDERS, arg) && getCredential(PROVIDERS[arg].envKey) ? arg : null;
  for (const [name, p] of Object.entries(PROVIDERS)) {
    if (getCredential(p.envKey)) return name;
  }
  return null;
}

function postJSON(urlStr, body, headers, timeoutMs = 120000) {
  return new Promise((resolve, reject) => {
    const url = new URL(urlStr);
    const data = JSON.stringify(body);
    const req = https.request({
      hostname: url.hostname,
      path: url.pathname + url.search,
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data), ...headers },
    }, res => {
      let chunks = '';
      res.on('data', c => { chunks += c; });
      res.on('end', () => resolve({ status: res.statusCode, body: chunks }));
    });
    req.setTimeout(timeoutMs, () => req.destroy(new Error('council request timeout')));
    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

async function callOpenAICompat(provider, model, system, user) {
  const start = Date.now();
  const url = `${provider.baseUrl}/chat/completions`;
  const res = await postJSON(url, {
    model,
    messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
    max_tokens: 4000,
    temperature: 1,
  }, { Authorization: `Bearer ${getCredential(provider.envKey)}` });
  const elapsed = Date.now() - start;
  if (res.status >= 400) return { success: false, content: `[ERROR ${res.status}: ${res.body.slice(0, 300)}]`, model, latency_ms: elapsed };
  let data;
  try { data = JSON.parse(res.body); } catch (e) { return { success: false, content: `[parse-error]`, model, latency_ms: elapsed }; }
  const content = data.choices?.[0]?.message?.content || '';
  return { success: true, content, model, latency_ms: elapsed, tokens: data.usage || {} };
}

async function callAnthropic(provider, model, system, user) {
  const start = Date.now();
  const url = `${provider.baseUrl}/v1/messages`;
  const res = await postJSON(url, {
    model,
    max_tokens: 4000,
    system,
    messages: [{ role: 'user', content: user }],
  }, {
    'x-api-key': getCredential(provider.envKey),
    'anthropic-version': '2023-06-01',
  });
  const elapsed = Date.now() - start;
  if (res.status >= 400) return { success: false, content: `[ERROR ${res.status}: ${res.body.slice(0, 300)}]`, model, latency_ms: elapsed };
  let data;
  try { data = JSON.parse(res.body); } catch { return { success: false, content: '[parse-error]', model, latency_ms: elapsed }; }
  const content = (data.content || []).map(b => b.text || '').join('');
  return { success: true, content, model, latency_ms: elapsed, tokens: data.usage || {} };
}

function parseArgs(argv) {
  const out = { _: [] };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a.startsWith('--')) {
      const key = a.slice(2);
      const next = argv[i + 1];
      if (next && !next.startsWith('--')) { out[key] = next; i++; }
      else out[key] = true;
    } else out._.push(a);
  }
  return out;
}

function ts() { return new Date().toISOString().replace(/[:.]/g, '-'); }

function persistToWiki(slug, sessionId, output) {
  const distPath = path.join(PRO_WORKFLOW_ROOT, 'dist', 'db', 'store.js');
  if (!fs.existsSync(distPath)) return null;
  const { createStore } = require(distPath);
  const store = createStore();
  try {
    const wiki = store.getWiki(slug);
    if (!wiki) return null;
    const relPath = path.posix.join('derived', 'council', `${sessionId}.md`);
    const fileAbs = path.join(wiki.root_path, relPath);
    fs.mkdirSync(path.dirname(fileAbs), { recursive: true });
    fs.writeFileSync(fileAbs, output);
    store.upsertWikiPage({
      wiki_slug: slug,
      rel_path: relPath,
      title: `Council session ${sessionId}`,
      summary: output.slice(0, 500),
      content: output,
      page_type: 'council',
      content_hash: null,
    });
    return fileAbs;
  } finally { store.close(); }
}

async function cmdRun(args) {
  const query = args._[0];
  if (!query) { console.error('run: query required'); process.exit(1); }
  const providerName = pickProvider(args.provider);
  if (!providerName) { console.error('No configured provider. Set a key in plugin settings, or use a PRO_WORKFLOW_*_API_KEY variable for the standalone CLI.'); process.exit(2); }
  const provider = PROVIDERS[providerName];
  if (!provider.baseUrl) { console.error(`provider ${providerName} requires LLM_COUNCIL_BASE_URL`); process.exit(2); }

  const models = (args.models ? String(args.models).split(',') : provider.defaultModels).filter(Boolean);
  const chairman = args.chairman || provider.defaultChairman;
  if (!models.length) { console.error('no models — pass --models'); process.exit(2); }
  if (!chairman) { console.error('no chairman — pass --chairman'); process.exit(2); }

  const sessionId = ts();
  const sessionDir = path.join(COUNCIL_ROOT, sessionId);
  fs.mkdirSync(sessionDir, { recursive: true });

  fs.writeFileSync(path.join(sessionDir, 'config.json'), JSON.stringify({ query, models, chairman, provider: providerName }, null, 2));

  function settledToEntry(model, settled) {
    if (settled.status === 'fulfilled') return settled.value;
    return { success: false, content: `[ERROR: ${settled.reason?.message || settled.reason}]`, model, latency_ms: 0 };
  }

  // Phase 1
  const sysIndep = 'You are participating in an LLM council deliberation. Provide your best, most thoughtful response to the query. Be comprehensive but focused.';
  const phase1Settled = await Promise.allSettled(models.map(m => provider.call(provider, m, sysIndep, query)));
  const phase1Entries = phase1Settled.map((s, i) => settledToEntry(models[i], s));
  const phase1 = Object.fromEntries(models.map((m, i) => [m, phase1Entries[i]]));
  fs.writeFileSync(path.join(sessionDir, 'phase1_responses.json'), JSON.stringify(phase1, null, 2));

  // Phase 2
  const labels = ['A', 'B', 'C', 'D', 'E', 'F', 'G'].slice(0, models.length);
  const labelOf = Object.fromEntries(models.map((m, i) => [m, labels[i]]));
  const anon = models.map(m => `=== Response ${labelOf[m]} ===\n${phase1[m].content}`).join('\n\n');
  const sysRank = (own) => `You are ranking AI responses objectively. Your own response is labeled '${own}'.`;
  const userRank = `QUERY:\n${query}\n\nRESPONSES:\n${anon}\n\nRank from BEST to WORST. Format:\nRANKINGS:\n1. [Letter] - [reason]\n2. [Letter] - [reason]\n...`;
  const phase2Settled = await Promise.allSettled(models.map(m => provider.call(provider, m, sysRank(labelOf[m]), userRank)));
  const phase2Entries = phase2Settled.map((s, i) => settledToEntry(models[i], s));
  const phase2 = { label_of: labelOf, rankings: Object.fromEntries(models.map((m, i) => [m, phase2Entries[i]])) };
  fs.writeFileSync(path.join(sessionDir, 'phase2_rankings.json'), JSON.stringify(phase2, null, 2));

  // Phase 3
  const responsesText = models.map(m => `=== ${labelOf[m]}: ${m} ===\n${phase1[m].content}`).join('\n\n');
  const rankingsText = models.map(m => `[${m}'s Rankings]\n${phase2.rankings[m].content}`).join('\n\n');
  const sysSynth = 'You are the Chairman of an LLM Council. Synthesize multiple AI perspectives into a definitive, comprehensive response.';
  const userSynth = `ORIGINAL QUERY:\n${query}\n\nINDIVIDUAL RESPONSES:\n${responsesText}\n\nMODEL RANKINGS:\n${rankingsText}\n\nProduce the FINAL SYNTHESIS:`;
  const synth = await provider.call(provider, chairman, sysSynth, userSynth);
  fs.writeFileSync(path.join(sessionDir, 'phase3_synthesis.txt'), synth.content);

  // Render
  const out = [];
  out.push(`# LLM Council Deliberation`);
  out.push(`Session: ${sessionId} · Provider: ${providerName}`);
  out.push('');
  out.push(`**Query:** ${query}`);
  out.push(`**Council:** ${models.join(', ')}`);
  out.push(`**Chairman:** ${chairman}`);
  out.push('');
  out.push('## Phase 1 — Individual responses');
  for (const m of models) {
    out.push(`### [${labelOf[m]}] ${m} (${phase1[m].latency_ms}ms)`);
    out.push(phase1[m].content);
    out.push('');
  }
  out.push('## Phase 2 — Cross-model rankings');
  for (const m of models) {
    out.push(`### ${m}`);
    out.push(phase2.rankings[m].content);
    out.push('');
  }
  out.push('## Phase 3 — Chairman synthesis');
  out.push(`### ${chairman}`);
  out.push(synth.content);

  const md = out.join('\n');
  fs.writeFileSync(path.join(sessionDir, 'final_output.md'), md);

  if (args.wiki) {
    const wikiPath = persistToWiki(args.wiki, sessionId, md);
    if (wikiPath) console.error(`[council] persisted to ${wikiPath}`);
    else console.error(`[council] wiki ${args.wiki} not found, skipping persist`);
  }

  console.log(md);
}

function cmdProviders() {
  const rows = Object.entries(PROVIDERS).map(([name, p]) => ({
    name,
    env_var: `PRO_WORKFLOW_${p.envKey}`,
    has_key: !!getCredential(p.envKey),
    base_url: p.baseUrl || '(unset)',
    default_models: p.defaultModels,
    default_chairman: p.defaultChairman,
  }));
  console.log(JSON.stringify(rows, null, 2));
}

function cmdShow(args) {
  const id = args._[0];
  if (!id) { console.error('show: session-id required'); process.exit(1); }
  const dir = path.join(COUNCIL_ROOT, id);
  const file = path.join(dir, 'final_output.md');
  if (!fs.existsSync(file)) { console.error('session not found'); process.exit(1); }
  console.log(fs.readFileSync(file, 'utf8'));
}

function usage() {
  console.error(`Usage:
  council.js run "<query>" [--models id1,id2,id3] [--chairman id] [--provider name] [--wiki slug]
  council.js providers
  council.js show <session-id>`);
  process.exit(1);
}

async function main() {
  const [, , cmd, ...rest] = process.argv;
  const args = parseArgs(rest);
  switch (cmd) {
    case 'run': await cmdRun(args); break;
    case 'providers': cmdProviders(); break;
    case 'show': cmdShow(args); break;
    default: usage();
  }
}

main().catch(e => { console.error(e); process.exit(1); });

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { CREDENTIAL_NAMES, getCredential } = require('../lib/credentials.js');

const names = [
  'ANTHROPIC_API_KEY',
  'OPENAI_API_KEY',
  'OPENROUTER_API_KEY',
  'FIREWORKS_API_KEY',
  'VOYAGE_API_KEY',
  'LLM_COUNCIL_API_KEY',
  'GITHUB_TOKEN',
  'TYPESAFE_API_KEY',
  'LAYA_API_KEY',
];

test('credential options cover every supported authenticated provider', () => {
  assert.deepEqual(CREDENTIAL_NAMES, names);
});

for (const name of names) {
  test(`${name} requires explicit configuration and prefers the plugin option`, () => {
    const option = `CLAUDE_PLUGIN_OPTION_${name}`;
    const standalone = `PRO_WORKFLOW_${name}`;
    assert.equal(getCredential(name, {}), undefined);
    assert.equal(getCredential(name, { [name]: 'ambient', GH_TOKEN: 'ambient-gh' }), undefined);
    assert.equal(getCredential(name, { [standalone]: ' standalone ' }), 'standalone');
    assert.equal(getCredential(name, { [option]: ' plugin ', [standalone]: 'standalone', [name]: 'ambient' }), 'plugin');
    for (const value of ['', '  ', '${user_config.' + name + '}', ' ${user_config.' + name + '} ']) {
      assert.equal(getCredential(name, { [option]: value, [standalone]: 'standalone', [name]: 'ambient' }), undefined);
      assert.equal(getCredential(name, { [standalone]: value, [name]: 'ambient' }), undefined);
    }
  });
}

test('credential resolver rejects unknown options and non-string values', () => {
  assert.throws(() => getCredential('UNDECLARED_API_KEY', {}), /Unknown credential option/);
  assert.equal(getCredential('OPENAI_API_KEY', { PRO_WORKFLOW_OPENAI_API_KEY: 123 }), undefined);
  assert.equal(getCredential('OPENAI_API_KEY', { CLAUDE_PLUGIN_OPTION_OPENAI_API_KEY: false, PRO_WORKFLOW_OPENAI_API_KEY: 'standalone' }), undefined);
});

import { test, type TestContext } from 'node:test';
import assert from 'node:assert/strict';
import https from 'node:https';
import { EventEmitter } from 'node:events';
import type { ClientRequest, IncomingMessage, OutgoingHttpHeaders } from 'node:http';
import { CREDENTIAL_NAMES } from '../../../scripts/lib/credentials.js';
import { getEmbeddingProvider } from '../../search/embeddings';
import { callLLM, type Provider } from '../llm';

function configureEnv(t: TestContext, values: Record<string, string>) {
  const keys = [...CREDENTIAL_NAMES.flatMap(name => [name, `PRO_WORKFLOW_${name}`, `CLAUDE_PLUGIN_OPTION_${name}`]), 'GH_TOKEN', 'PROWORKFLOW_EMBED_MODEL'];
  const previous = new Map(keys.map(key => [key, process.env[key]]));
  for (const key of keys) delete process.env[key];
  Object.assign(process.env, values);
  t.after(() => {
    for (const [key, value] of previous) {
      if (value === undefined) delete process.env[key];
      else process.env[key] = value;
    }
  });
}

function mockTransport(t: TestContext, payload: unknown) {
  const requests: { options: https.RequestOptions; body: string }[] = [];
  const request = (options: https.RequestOptions, callback: (response: IncomingMessage) => void) => {
    const record = { options, body: '' };
    requests.push(record);
    const req = Object.assign(new EventEmitter(), {
      write(body: string) { record.body += body; },
      setTimeout() { return req; },
      destroy(error: Error) { req.emit('error', error); return req; },
      end() {
        queueMicrotask(() => {
          const res = Object.assign(new EventEmitter(), { statusCode: 200 });
          callback(res as IncomingMessage);
          res.emit('data', Buffer.from(JSON.stringify(payload)));
          res.emit('end');
        });
        return req;
      },
    });
    return req as unknown as ClientRequest;
  };
  t.mock.method(https, 'request', request as typeof https.request);
  return requests;
}

test('embedding selection ignores ambient provider credentials', t => {
  configureEnv(t, { OPENAI_API_KEY: 'ambient-openai', VOYAGE_API_KEY: 'ambient-voyage' });
  const requests = mockTransport(t, {});
  assert.equal(getEmbeddingProvider(), null);
  assert.equal(requests.length, 0);
});

for (const prefix of ['CLAUDE_PLUGIN_OPTION_', 'PRO_WORKFLOW_']) {
  for (const [name, key, host] of [
    ['openai', 'OPENAI_API_KEY', 'api.openai.com'],
    ['voyage', 'VOYAGE_API_KEY', 'api.voyageai.com'],
  ]) {
    test(`${name} embeddings use ${prefix} credentials on the request`, async t => {
      configureEnv(t, { [prefix + key]: 'configured-key', OPENAI_API_KEY: 'ambient-openai', VOYAGE_API_KEY: 'ambient-voyage' });
      const requests = mockTransport(t, { data: [{ embedding: [0.25, 0.5] }] });
      const provider = getEmbeddingProvider();
      assert.ok(provider);
      assert.equal(provider.name, name);
      const vectors = await provider.embed(['private query']);
      assert.deepEqual(Array.from(vectors[0]), [0.25, 0.5]);
      assert.equal(requests.length, 1);
      assert.equal(requests[0].options.hostname, host);
      assert.equal((requests[0].options.headers as OutgoingHttpHeaders).Authorization, 'Bearer configured-key');
      assert.deepEqual(JSON.parse(requests[0].body).input, ['private query']);
    });
  }
}

const providers: { provider: Provider; key: string; host: string; model: string }[] = [
  { provider: 'anthropic', key: 'ANTHROPIC_API_KEY', host: 'api.anthropic.com', model: 'claude-haiku-4-5' },
  { provider: 'openai', key: 'OPENAI_API_KEY', host: 'api.openai.com', model: 'gpt-4o-mini' },
  { provider: 'openrouter', key: 'OPENROUTER_API_KEY', host: 'openrouter.ai', model: 'gpt-4o-mini' },
  { provider: 'fireworks', key: 'FIREWORKS_API_KEY', host: 'api.fireworks.ai', model: 'gpt-4o-mini' },
];

for (const { provider, key, host, model } of providers) {
  test(`${provider} optimizer rejects an ambient credential before requesting`, async t => {
    configureEnv(t, { [key]: 'ambient-key' });
    const requests = mockTransport(t, {});
    await assert.rejects(callLLM({ provider, model, system: 'system', user: 'private input' }), new RegExp(`PRO_WORKFLOW_${key}`));
    assert.equal(requests.length, 0);
  });

  for (const prefix of ['CLAUDE_PLUGIN_OPTION_', 'PRO_WORKFLOW_']) {
    test(`${provider} optimizer uses ${prefix} credentials on the request`, async t => {
      configureEnv(t, { [prefix + key]: 'configured-key', [key]: 'ambient-key' });
      const payload = provider === 'anthropic'
        ? { content: [{ type: 'text', text: 'result' }], usage: { input_tokens: 12, output_tokens: 3 } }
        : { choices: [{ message: { content: 'result' } }], usage: { prompt_tokens: 12, completion_tokens: 3 } };
      const requests = mockTransport(t, payload);
      const result = await callLLM({ provider, model, system: 'system', user: 'private input' });
      assert.equal(result.text, 'result');
      assert.equal(result.inputTokens, 12);
      assert.equal(result.outputTokens, 3);
      assert.ok(result.costUsd > 0);
      assert.equal(requests.length, 1);
      assert.equal(requests[0].options.host, host);
      const authHeader = provider === 'anthropic' ? 'x-api-key' : 'authorization';
      const authValue = provider === 'anthropic' ? 'configured-key' : 'Bearer configured-key';
      assert.equal((requests[0].options.headers as OutgoingHttpHeaders)[authHeader], authValue);
      assert.equal(JSON.parse(requests[0].body).messages.at(-1).content, 'private input');
    });
  }
}

const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

const scriptPath = path.join(__dirname, '..', '..', 'skills', 'wiki-research-loop', 'scripts', 'research-loop.js');

function fixture(t) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'pro-workflow-fetchers-'));
  t.after(() => fs.rmSync(root, { recursive: true, force: true }));
  const scripts = path.join(root, 'skills', 'wiki-research-loop', 'scripts');
  const home = path.join(root, 'home');
  const wiki = path.join(root, 'wiki');
  const bundled = path.join(scripts, 'source-fetchers');
  const custom = path.join(home, '.pro-workflow', 'fetchers');
  const dist = path.join(root, 'dist', 'db');
  for (const dir of [bundled, custom, dist, wiki]) fs.mkdirSync(dir, { recursive: true });
  const entrypoint = path.join(scripts, 'research-loop.js');
  fs.copyFileSync(scriptPath, entrypoint);
  fs.writeFileSync(path.join(dist, 'store.js'), `
    module.exports.createStore = () => {
      let pending = true;
      return {
        getWiki: () => ({ root_path: ${JSON.stringify(wiki)} }),
        listWikiPages: () => [],
        claimPendingSeed: () => {
          if (!pending) return null;
          pending = false;
          return { id: 1, query: 'local fixture', depth: 0 };
        },
        setSeedStatus() {},
        close() {},
      };
    };
  `);
  for (const [dir, label] of [[bundled, 'bundled'], [custom, 'custom']]) {
    fs.writeFileSync(path.join(dir, 'github.js'), `
      const fs = require('node:fs');
      fs.writeFileSync(${JSON.stringify(path.join(root, `${label}-loaded`))}, 'loaded');
      module.exports = {
        match: () => true,
        fetch: async () => {
          fs.writeFileSync(${JSON.stringify(path.join(root, 'selected-fetcher'))}, ${JSON.stringify(label)});
          return [];
        },
      };
    `);
  }
  return { root, home, entrypoint };
}

function runResearch({ home, entrypoint }, env = {}) {
  const result = spawnSync(process.execPath, [entrypoint, 'run', 'fixture', '--force', '--fetchers', 'github', '--max-pages', '1'], {
    env: { HOME: home, USERPROFILE: home, ...env },
    encoding: 'utf8',
    timeout: 5000,
  });
  assert.equal(result.status, 0, result.stderr);
  assert.equal(JSON.parse(result.stdout).halted, 'queue-empty');
}

test('bundled-only research never requires a custom fetcher with the same name', t => {
  const files = fixture(t);
  runResearch(files, { PRO_WORKFLOW_BUNDLED_FETCHERS_ONLY: '1' });
  assert.equal(fs.existsSync(path.join(files.root, 'bundled-loaded')), true);
  assert.equal(fs.existsSync(path.join(files.root, 'custom-loaded')), false);
  assert.equal(fs.readFileSync(path.join(files.root, 'selected-fetcher'), 'utf8'), 'bundled');
});

test('standalone research still loads custom fetchers and allows overriding built-ins', t => {
  const files = fixture(t);
  runResearch(files);
  assert.equal(fs.existsSync(path.join(files.root, 'bundled-loaded')), true);
  assert.equal(fs.existsSync(path.join(files.root, 'custom-loaded')), true);
  assert.equal(fs.readFileSync(path.join(files.root, 'selected-fetcher'), 'utf8'), 'custom');
});

#!/usr/bin/env node
const fs = require('fs');
const path = require('path');
const os = require('os');

process.stdin.setEncoding('utf8');
let data = '';
process.stdin.on('data', chunk => { data += chunk; });
process.stdin.on('end', () => {
  try {
    const input = JSON.parse(data);
    const trigger = input.trigger || 'unknown';
    const cwd = process.cwd();

    if (trigger === 'init') {
      console.error('[ProWorkflow] Initial setup detected');

      const checks = [];
