import Database from 'better-sqlite3';
import { Learning } from '../db/store';

export interface SearchResult extends Learning {
  rank: number;
  snippet?: string;
}

export interface SearchOptions {
  limit?: number;
  project?: string;
  category?: string;
}

export function searchLearnings(
  db: Database.Database,
  query: string,
  options: SearchOptions = {}
): SearchResult[] {
  const { limit = 10, project, category } = options;

  const sanitizedQuery = sanitizeQuery(query);

  if (!sanitizedQuery) {
    return [];
  }

  let sql = `
    SELECT
      learnings.*,
      bm25(learnings_fts, 1.0, 2.0, 1.0, 1.0) as rank,
      snippet(learnings_fts, 1, '<mark>', '</mark>', '...', 32) as snippet
    FROM learnings
    JOIN learnings_fts ON learnings.id = learnings_fts.rowid
    WHERE learnings_fts MATCH ?
  `;

  const params: (string | number)[] = [sanitizedQuery];

  if (project) {
    sql += ` AND (learnings.project = ? OR learnings.project IS NULL)`;
    params.push(project);
  }

  if (category) {
    sql += ` AND learnings.category = ?`;
    params.push(category);
  }

  sql += ` ORDER BY rank LIMIT ?`;
  params.push(limit);

  const stmt = db.prepare(sql);
  return stmt.all(...params) as SearchResult[];
}

export function searchByCategory(
  db: Database.Database,
  category: string,
  options: SearchOptions = {}
): Learning[] {
  const { limit = 10, project } = options;

  let sql = `
    SELECT * FROM learnings
    WHERE category = ?
  `;

  const params: (string | number)[] = [category];

  if (project) {
    sql += ` AND (project = ? OR project IS NULL)`;
    params.push(project);
  }

  sql += ` ORDER BY times_applied DESC, created_at DESC LIMIT ?`;
  params.push(limit);

  const stmt = db.prepare(sql);
  return stmt.all(...params) as Learning[];
}

export function getRelatedLearnings(
  db: Database.Database,
  learningId: number,
  limit: number = 5
): SearchResult[] {
  const learningStmt = db.prepare(`SELECT * FROM learnings WHERE id = ?`);
  const learning = learningStmt.get(learningId) as Learning | undefined;

  if (!learning) {
    return [];
  }

  const keywords = extractKeywords(learning.rule);
  if (keywords.length === 0) {
    return searchByCategory(db, learning.category, { limit }) as SearchResult[];
  }

  const query = keywords.join(' OR ');
  const results = searchLearnings(db, query, { limit: limit + 1 });

  return results.filter((r) => r.id !== learningId).slice(0, limit);
}

export function getMostAppliedLearnings(
  db: Database.Database,
  limit: number = 10
): Learning[] {
  const stmt = db.prepare(`
    SELECT * FROM learnings
    WHERE times_applied > 0
    ORDER BY times_applied DESC, created_at DESC
    LIMIT ?
  `);

  return stmt.all(limit) as Learning[];
}

export function getRecentLearnings(
  db: Database.Database,
  limit: number = 10,
  project?: string
): Learning[] {
  let sql = `SELECT * FROM learnings`;
  const params: (string | number)[] = [];

  if (project) {
    sql += ` WHERE project = ? OR project IS NULL`;
    params.push(project);
  }

  sql += ` ORDER BY created_at DESC LIMIT ?`;
  params.push(limit);

  const stmt = db.prepare(sql);
  return stmt.all(...params) as Learning[];
}

function sanitizeQuery(query: string): string {
  return query
    .replace(/[^\w\s*"]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .split(' ')
    .filter((word) => word.length > 0)
    .map((word) => {
      if (word.startsWith('"') && word.endsWith('"')) {
        return word;
      }
      if (!word.includes('*')) {
        return `${word}*`;
      }
      return word;
    })
    .join(' ');
}

function extractKeywords(text: string): string[] {
  const stopWords = new Set([
    'a', 'an', 'the', 'is', 'are', 'was', 'were', 'be', 'been',
    'being', 'have', 'has', 'had', 'do', 'does', 'did', 'will',
    'would', 'could', 'should', 'may', 'might', 'must', 'shall',
    'can', 'need', 'to', 'of', 'in', 'for', 'on', 'with', 'at',
    'by', 'from', 'as', 'into', 'through', 'during', 'before',
    'after', 'above', 'below', 'between', 'under', 'again',
    'further', 'then', 'once', 'here', 'there', 'when', 'where',
    'why', 'how', 'all', 'each', 'few', 'more', 'most', 'other',
    'some', 'such', 'no', 'nor', 'not', 'only', 'own', 'same',
    'so', 'than', 'too', 'very', 'just', 'and', 'but', 'if', 'or',
    'because', 'until', 'while', 'although', 'though', 'this',
    'that', 'these', 'those', 'it', 'its',
  ]);

  return text
    .toLowerCase()
    .replace(/[^\w\s]/g, ' ')
    .split(/\s+/)
    .filter((word) => word.length > 2 && !stopWords.has(word))
    .slice(0, 5);
}

import Database from 'better-sqlite3';
import * as https from 'https';
import { getCredential } from '../../scripts/lib/credentials.js';

export interface EmbeddingProvider {
  name: string;
  model: string;
  dim: number;
  embed(texts: string[]): Promise<Float32Array[]>;
}

function pickProvider(): EmbeddingProvider | null {
  const openaiKey = getCredential('OPENAI_API_KEY');
  if (openaiKey) return openai(openaiKey);
  const voyageKey = getCredential('VOYAGE_API_KEY');
  if (voyageKey) return voyage(voyageKey);
  return null;
}

function postJSON(urlStr: string, body: unknown, headers: Record<string, string>): Promise<{ status: number; body: string }> {
  return new Promise((resolve, reject) => {
    const url = new URL(urlStr);
    const data = JSON.stringify(body);
    const req = https.request({
      hostname: url.hostname,
      path: url.pathname + url.search,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data),
        ...headers,
      },
    }, res => {
      let chunks = '';
      res.on('data', c => { chunks += c; });
      res.on('end', () => resolve({ status: res.statusCode || 0, body: chunks }));
    });
    req.setTimeout(30000, () => req.destroy(new Error('embedding request timeout')));
    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

function openai(apiKey: string): EmbeddingProvider {
  const model = process.env.PROWORKFLOW_EMBED_MODEL || 'text-embedding-3-small';
  const dim = model === 'text-embedding-3-large' ? 3072 : 1536;
  return {
    name: 'openai', model, dim,
    async embed(texts) {
      const res = await postJSON('https://api.openai.com/v1/embeddings', { input: texts, model }, { Authorization: `Bearer ${apiKey}` });
      if (res.status >= 400) throw new Error(`openai embeddings ${res.status}: ${res.body.slice(0, 200)}`);
      const data = JSON.parse(res.body);
      return data.data.map((d: { embedding: number[] }) => Float32Array.from(d.embedding));
    },
  };
}

function voyage(apiKey: string): EmbeddingProvider {
  const model = process.env.PROWORKFLOW_EMBED_MODEL || 'voyage-3';
  return {
    name: 'voyage', model, dim: 1024,
    async embed(texts) {
      const res = await postJSON('https://api.voyageai.com/v1/embeddings', { input: texts, model }, { Authorization: `Bearer ${apiKey}` });
      if (res.status >= 400) throw new Error(`voyage embeddings ${res.status}: ${res.body.slice(0, 200)}`);
      const data = JSON.parse(res.body);
      return data.data.map((d: { embedding: number[] }) => Float32Array.from(d.embedding));
    },
  };
}

export function getEmbeddingProvider(): EmbeddingProvider | null {
  return pickProvider();
}

function f32ToBlob(v: Float32Array): Buffer {
  return Buffer.from(v.buffer, v.byteOffset, v.byteLength);
}

function blobToF32(buf: Buffer): Float32Array {
  return new Float32Array(buf.buffer, buf.byteOffset, buf.byteLength / 4);
}

export function upsertEmbedding(db: Database.Database, pageId: number, provider: EmbeddingProvider, vector: Float32Array): void {
  if (vector.length !== provider.dim) throw new Error(`dim mismatch: ${vector.length} vs ${provider.dim}`);
  db.prepare(`
    INSERT INTO wiki_embeddings (page_id, model, dim, vector)
    VALUES (?, ?, ?, ?)
    ON CONFLICT(page_id) DO UPDATE SET
      model = excluded.model,
      dim = excluded.dim,
      vector = excluded.vector,
      computed_at = datetime('now')
  `).run(pageId, `${provider.name}:${provider.model}`, provider.dim, f32ToBlob(vector));
}

function cosine(a: Float32Array, b: Float32Array): number {
  if (a.length !== b.length) return 0;
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    na += a[i] * a[i];
    nb += b[i] * b[i];
  }
  if (na === 0 || nb === 0) return 0;
  return dot / (Math.sqrt(na) * Math.sqrt(nb));
}

export interface VectorHit {
  page_id: number;
  similarity: number;
}

export function vectorSearch(db: Database.Database, queryVec: Float32Array, opts: { wikiSlug?: string; limit?: number } = {}): VectorHit[] {
  const limit = opts.limit ?? 10;
  const dim = queryVec.length;
  const sql = opts.wikiSlug
    ? `SELECT e.page_id, e.vector FROM wiki_embeddings e JOIN wiki_pages p ON p.id = e.page_id WHERE p.wiki_slug = ? AND e.dim = ?`
    : `SELECT e.page_id, e.vector FROM wiki_embeddings e WHERE e.dim = ?`;
  const rows = opts.wikiSlug ? db.prepare(sql).all(opts.wikiSlug, dim) : db.prepare(sql).all(dim);
  const scored: VectorHit[] = [];
  for (const r of rows as { page_id: number; vector: Buffer }[]) {
    const v = blobToF32(r.vector);
    if (v.length !== dim) continue;
    scored.push({ page_id: r.page_id, similarity: cosine(queryVec, v) });
  }
  scored.sort((a, b) => b.similarity - a.similarity);
  return scored.slice(0, limit);
}

export function reciprocalRankFusion<T>(lists: T[][], keyFn: (x: T) => string, k = 60): { key: string; score: number }[] {
  const scores = new Map<string, number>();
  for (const list of lists) {
    list.forEach((item, i) => {
      const key = keyFn(item);
      scores.set(key, (scores.get(key) || 0) + 1 / (k + i + 1));
    });
  }
  return Array.from(scores.entries())
    .map(([key, score]) => ({ key, score }))
    .sort((a, b) => b.score - a.score);
}

import * as https from 'node:https';
import { getCredential } from '../../scripts/lib/credentials.js';

const DEFAULT_TIMEOUT_MS = 120_000;

export type Provider = 'anthropic' | 'openai' | 'openrouter' | 'fireworks';

export interface LLMRequest {
  provider: Provider;
  model: string;
  system: string;
  user: string;
  maxTokens?: number;
  temperature?: number;
}

export interface LLMResponse {
  text: string;
  inputTokens: number;
  outputTokens: number;
  costUsd: number;
}

const PROVIDER_CFG: Record<Provider, { host: string; path: string; envKey: string }> = {
  anthropic: { host: 'api.anthropic.com', path: '/v1/messages', envKey: 'ANTHROPIC_API_KEY' },
  openai: { host: 'api.openai.com', path: '/v1/chat/completions', envKey: 'OPENAI_API_KEY' },
  openrouter: { host: 'openrouter.ai', path: '/api/v1/chat/completions', envKey: 'OPENROUTER_API_KEY' },
  fireworks: { host: 'api.fireworks.ai', path: '/inference/v1/chat/completions', envKey: 'FIREWORKS_API_KEY' },
};

const PRICE_PER_M_TOKENS: Record<string, { input: number; output: number }> = {
  'claude-fable-5-1': { input: 10, output: 50 },
  'claude-opus-5-5': { input: 4, output: 20 },
  'claude-opus-5': { input: 5, output: 25 },
  'claude-opus-4-8': { input: 5, output: 25 },
  'claude-opus-4-7': { input: 5, output: 25 },
  'claude-sonnet-5': { input: 2, output: 10 },
  'claude-sonnet-4-6': { input: 3, output: 15 },
  'claude-haiku-4-5': { input: 1, output: 5 },
  'claude-haiku-4-5-20251001': { input: 1, output: 5 },
  'gpt-4o': { input: 2.5, output: 10 },
  'gpt-4o-mini': { input: 0.15, output: 0.6 },
};

export async function callLLM(req: LLMRequest): Promise<LLMResponse> {
  const cfg = PROVIDER_CFG[req.provider];
  const apiKey = getCredential(cfg.envKey);
  if (!apiKey) throw new Error(`Configure ${req.provider} in plugin settings, or set PRO_WORKFLOW_${cfg.envKey} for the standalone CLI`);

  const body = req.provider === 'anthropic'
    ? buildAnthropicBody(req)
    : buildOpenAIBody(req);

  const headers: Record<string, string> = req.provider === 'anthropic'
    ? { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' }
    : { authorization: `Bearer ${apiKey}`, 'content-type': 'application/json' };

  const price = PRICE_PER_M_TOKENS[req.model];
  if (!price) {
    const known = Object.keys(PRICE_PER_M_TOKENS).join(', ');
    throw new Error(
      `Unknown model "${req.model}". Budget cap cannot be enforced. ` +
      `Add a price entry to PRICE_PER_M_TOKENS in src/optimizer/llm.ts or pick one of: ${known}.`,
    );
  }

  const raw = await postJson(cfg.host, cfg.path, headers, body);
  const parsed = JSON.parse(raw);
  const text = extractText(req.provider, parsed);
  const usage = extractUsage(req.provider, parsed);
  const costUsd = (usage.input / 1_000_000) * price.input + (usage.output / 1_000_000) * price.output;

  return { text, inputTokens: usage.input, outputTokens: usage.output, costUsd };
}

function buildAnthropicBody(req: LLMRequest): string {
  return JSON.stringify({
    model: req.model,
    max_tokens: req.maxTokens ?? 4096,
    system: req.system,
    messages: [{ role: 'user', content: req.user }],
  });
}

function buildOpenAIBody(req: LLMRequest): string {
  return JSON.stringify({
    model: req.model,
    max_tokens: req.maxTokens ?? 4096,
    temperature: req.temperature ?? 0.2,
    messages: [
      { role: 'system', content: req.system },
      { role: 'user', content: req.user },
    ],
  });
}

function extractText(provider: Provider, body: unknown): string {
  const obj = body as Record<string, unknown>;
  if (provider === 'anthropic') {
    const content = obj.content as Array<{ type: string; text?: string }> | undefined;
    return content?.find((c) => c.type === 'text')?.text ?? '';
  }
  const choices = obj.choices as Array<{ message?: { content?: string } }> | undefined;
  return choices?.[0]?.message?.content ?? '';
}

function extractUsage(provider: Provider, body: unknown): { input: number; output: number } {
  const obj = body as Record<string, unknown>;
  if (provider === 'anthropic') {
    const u = obj.usage as { input_tokens?: number; output_tokens?: number } | undefined;
    return { input: u?.input_tokens ?? 0, output: u?.output_tokens ?? 0 };
  }
  const u = obj.usage as { prompt_tokens?: number; completion_tokens?: number } | undefined;
  return { input: u?.prompt_tokens ?? 0, output: u?.completion_tokens ?? 0 };
}

function postJson(host: string, path: string, headers: Record<string, string>, body: string): Promise<string> {
  const timeoutMs = parseInt(process.env.SKILL_OPTIMIZER_TIMEOUT_MS ?? '', 10) || DEFAULT_TIMEOUT_MS;
  return new Promise((resolve, reject) => {
    let timer: NodeJS.Timeout | null = null;
    let settled = false;
    const settle = (fn: () => void) => {
      if (settled) return;
      settled = true;
      if (timer) {
        clearTimeout(timer);
        timer = null;
      }
      fn();
    };
    const req = https.request(
      { host, path, method: 'POST', headers: { ...headers, 'content-length': Buffer.byteLength(body).toString() } },
      (res) => {
        const chunks: Buffer[] = [];
        res.on('data', (c) => chunks.push(c));
        res.on('end', () => {
          const text = Buffer.concat(chunks).toString('utf8');
          if ((res.statusCode ?? 500) >= 400) {
            settle(() => reject(new Error(`HTTP ${res.statusCode}: ${text.slice(0, 500)}`)));
          } else {
            settle(() => resolve(text));
          }
        });
        res.on('error', (err) => settle(() => reject(err)));
      },
    );
    req.on('error', (err) => settle(() => reject(err)));
    timer = setTimeout(() => {
      req.destroy(new Error(`Request timed out after ${timeoutMs}ms`));
    }, timeoutMs);
    req.write(body);
    req.end();
  });
}
